import itertools
from collections import deque

def solve_small(N):
    swaps = []
    for i in range(N):
        swaps.append(tuple(sorted((i, (i + 1) % N))))

    initial = tuple(range(N))
    dist = {initial: 0}
    queue = deque([initial])

    while queue:
        curr = queue.popleft()
        d = dist[curr]
        for s in swaps:
            lst = list(curr)
            i, j = s
            lst[i], lst[j] = lst[j], lst[i]
            next_perm = tuple(lst)
            if next_perm not in dist:
                dist[next_perm] = d + 1
                queue.append(next_perm)

    max_min_dist = 0
    for pi in dist:
        min_d = float('inf')
        for k in range(N):
            rotated_pi = pi[k:] + pi[:k]
            if rotated_pi in dist:
                min_d = min(min_d, dist[rotated_pi])
        if min_d > max_min_dist:
            max_min_dist = min_d

    return max_min_dist

for n in range(3, 9):
    print(f"N={n}, f(N)={solve_small(n)}")

